"""Build a local review gallery from captured route evidence (no credentials)."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
report=json.loads((ROOT/'report.json').read_text(encoding='utf-8'))
report['screens']+=json.loads((ROOT/'overlays.json').read_text(encoding='utf-8'))
labels={'teacher-sports':'体育课程','manage-activities':'活动管理','academic':'学习社区入口','teaching':'课程服务入口','alumni-people':'校友名录','alumni-bookings':'校友预约','home':'首页','discover':'发现','campus':'校园','me':'我的','activity':'活动详情','schedule':'我的安排','coffee':'师生交流','community':'校园社区','partners':'找搭子','teams':'组队管理','messages':'会话','notifications':'通知','settings':'设置','ai':'校园 AI','login':'登录','register':'注册','forgot-password':'找回密码','identity':'校园身份核验','welcome':'校园启动页'}
for e in report['screens']:
 e['label']=labels.get(e['id'],e['title'].replace('\n',' '));e['before']=(ROOT/f'before-{e["id"]}-desktop.png').exists()
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>会同里 · 全界面设计</title><style>
@font-face{font-family:MiSans;src:url('/fonts/misans/MiSans-Regular.woff2')}@font-face{font-family:WenKai;src:url('/fonts/lxgw-wenkai/BNBUWenKai-Medium.woff2')}*{box-sizing:border-box}body{margin:0;background:#faf9f6;color:#263c35;font:15px/1.65 MiSans,sans-serif}button,input{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,a:focus-visible{outline:2px solid #426575;outline-offset:3px}header{padding:24px 32px;border-bottom:1px solid #dce2d8}h1{font:500 32px/1.4 WenKai,serif;margin:0 0 8px}p{margin:0;color:#65726a}nav{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0 0}button{border:1px solid #d5dcd2;border-radius:6px;background:transparent;color:inherit;padding:9px 16px;min-height:44px}button[aria-pressed=true]{background:#e8eee9;border-color:#aabdac}main{display:grid;grid-template-columns:250px minmax(0,1fr);min-height:calc(100vh - 210px)}aside{padding:24px 16px;border-right:1px solid #dce2d8;max-height:calc(100dvh - 210px);overflow:auto;position:sticky;top:0}aside input{width:100%;padding:12px;border:1px solid #d5dcd2;border-radius:6px;background:#fffefa;margin-bottom:12px}.pages{display:grid;gap:6px}.pages button{text-align:left;padding:10px 12px;width:100%}.pages small{display:block;color:#65726a;font-size:12px}.stage{min-width:0;padding:24px 28px}.stage-top{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}h2{font:500 27px/1.4 WenKai,serif;margin:0}a{color:#426575}.views{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:22px;align-items:start}figure{margin:0;min-width:0}figcaption{color:#65726a;margin-bottom:10px}figure img{display:block;width:100%;height:auto;border:1px solid #dce2d8;background:#fffefa}figure a{display:block}.tools{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.tools label{display:flex;gap:8px;align-items:center;min-height:44px}footer{padding:20px 32px;border-top:1px solid #dce2d8;color:#65726a;font-size:13px}@media(max-width:1050px){.views{grid-template-columns:minmax(0,1fr)}figure:last-child{max-width:390px}}@media(max-width:700px){header{padding:20px}main{display:block}aside{position:static;max-height:260px;border-bottom:1px solid #dce2d8}.pages{grid-template-columns:1fr 1fr}.stage{padding:20px}.views{gap:26px}h1{font-size:28px}}
</style><header><h1>会同里 · 全界面设计</h1><p>校园窗口 / 学生 · 教师 · 管理员 · 账号入口</p><p>45 个页面入口与 11 种弹窗的本地验收画面，使用模拟数据。选择页面查看手机与桌面，部分页面可对照本轮改动前的画面。</p><nav aria-label="按身份筛选"></nav></header><main><aside><input type="search" aria-label="查找页面" placeholder="查找页面"><div class="pages" aria-label="页面清单"></div></aside><section class="stage"><div class="stage-top"><div><h2 id="page-title"></h2><a id="route" target="_blank" rel="noreferrer">打开实际页面（需对应身份）</a></div><div class="tools"><label><input id="before" type="checkbox">本轮改动前</label><span id="count"></span></div></div><div class="views"><figure><figcaption>桌面 · 1440 × 900</figcaption><a id="desktop-link" target="_blank"><img id="desktop" alt=""></a></figure><figure><figcaption>手机 · 390 × 844</figcaption><a id="mobile-link" target="_blank"><img id="mobile" alt=""></a></figure></div></section></main><footer>已检查 320、390、720 和 1440 像素宽度。截图用于本地设计评审，不代表生产或真实设备验收。</footer><script>
const screens=__DATA__;const roles={all:'全部',student:'学生',teacher:'教师',admin:'管理员',public:'账号入口'};let role='all',chosen='campus';const search=document.querySelector('aside input');
function renderList(){const items=screens.filter(s=>(role==='all'||s.role===role)&&(s.label+s.id).toLowerCase().includes(search.value.toLowerCase()));const list=document.querySelector('.pages');list.replaceChildren();items.forEach(s=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-pressed',String(s.id===chosen));b.append(document.createTextNode(s.label));const small=document.createElement('small');small.textContent=roles[s.role];b.append(small);b.onclick=()=>{chosen=s.id;document.querySelector('#before').checked=false;show();renderList()};list.append(b)});document.querySelector('#count').textContent=items.length+' / '+screens.length+' 个画面'}
function show(){const s=screens.find(s=>s.id===chosen);document.querySelector('#page-title').textContent=s.label;const before=document.querySelector('#before');before.disabled=!s.before;if(!s.before)before.checked=false;for(const mode of ['desktop','mobile']){const src=(before.checked?'before-':'')+s.id+'-'+mode+'.png';document.querySelector('#'+mode).src=src;document.querySelector('#'+mode).alt=s.label+' · '+mode;document.querySelector('#'+mode+'-link').href=src}document.querySelector('#route').href=(s.role==='teacher'?'http://localhost:4174':'http://127.0.0.1:4174')+s.url}
Object.entries(roles).forEach(([key,name])=>{const b=document.createElement('button');b.type='button';b.textContent=name;b.setAttribute('aria-pressed',String(key===role));b.onclick=()=>{role=key;const first=screens.find(s=>role==='all'||s.role===role);if(first){chosen=first.id;show()}document.querySelectorAll('nav button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderList()};document.querySelector('nav').append(b)});search.oninput=renderList;document.querySelector('#before').onchange=show;show();renderList();
</script></html>'''
(ROOT/'index.html').write_text(html.replace('__DATA__',json.dumps(report['screens'],ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
